    setEnviando(true);
    try {
      const { token } = await cadastro({ ...form, ...arquivos });
      setMotoboyToken(token);
      refreshUserProfile(); // se era cliente logado, o role virou 'motoboy' no banco
      navigate('/motoboy');
    } catch (err) {
      setErro(err.message);
    } finally {
      setEnviando(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#F4F4F5] dark:bg-[#18181B] flex items-center justify-center p-4">
      <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-6 w-full max-w-md shadow-lg my-8">
