115	// Endereço estruturado (Estado/Cidade/Bairro/CEP) do estabelecimento — alimenta o
116	// filtro geográfico da home pública. Separado do resto da tela (que é config de
117	// pagamento/motoboy) porque usa outro endpoint (minha-empresa, não config).
118	// Endereço fica guardado como uma string só (address) — não é uma coluna separada de
119	// número. Pra evitar dono esquecer o número (some casos geocodificavam impreciso por
120	// causa disso), o form aqui separa Logradouro/Número visualmente e concatena os dois
121	// antes de salvar; ao carregar, tenta separar de volta um "..., 123" no fim da string
122	// já salva (melhor esforço — endereço antigo sem número cai tudo em Logradouro mesmo).
123	const separarNumero = (address) => {
124	  const m = (address ?? '').match(/^(.*?),?\s*(\d+[a-zA-Z]?)\s*$/);
125	  return m ? { logradouro: m[1].trim(), numero: m[2] } : { logradouro: address ?? '', numero: '' };
126	};
127	
128	const EnderecoCard = ({ geocodeFalhou }) => {
129	  const [form, setForm] = useState({ logradouro: '', numero: '', cep: '', neighborhood: '', city: '', state: '' });
130	  const [loading, setLoading] = useState(true);
131	  const [salvando, setSalvando] = useState(false);
132	  const [sucesso, setSucesso] = useState(false);
133	  const [erro, setErro] = useState(null);
134	  const [buscandoCep, setBuscandoCep] = useState(false);
135	
136	  const formatCEP = (v) => {
137	    const n = v.replace(/\D/g, '');
138	    return n.length <= 8 ? n.replace(/(\d{5})(\d{0,3})/, (_, a, b) => (b ? `${a}-${b}` : a)) : v;
139	  };
140	
141	  const handleCepChange = async (e) => {
142	    const formatted = formatCEP(e.target.value);
143	    setForm((f) => ({ ...f, cep: formatted }));
144	
145	    const digitos = formatted.replace(/\D/g, '');
146	    if (digitos.length !== 8) return;
147	    setBuscandoCep(true);
148	    const endereco = await buscarCep(digitos);
149	    setBuscandoCep(false);
150	    if (!endereco) return;
151	    setForm((f) => ({
152	      ...f,
153	      logradouro: endereco.logradouro || f.logradouro,
154	      neighborhood: endereco.bairro || f.neighborhood,
155	      city: endereco.cidade || f.city,
156	      state: endereco.estado || f.state,
157	    }));
158	  };
159	
160	  useEffect(() => {
161	    getMinhaEmpresa()
162	      .then((d) => {
163	        const e = d.empresa ?? {};
164	        const { logradouro, numero } = separarNumero(e.address);
165	        setForm({
166	          logradouro,
167	          numero,
168	          cep: e.cep ?? '',
169	          neighborhood: e.neighborhood ?? '',
170	          city: e.city ?? '',
171	          state: e.state ?? '',
172	        });
173	      })
174	      .catch((e) => setErro(e.message))
175	      .finally(() => setLoading(false));
176	  }, []);
177	
178	  const salvar = async (e) => {
179	    e.preventDefault();
180	    if (!form.logradouro.trim() || !form.numero.trim()) {
181	      setErro('Informe logradouro e número.');
182	      return;
183	    }
184	    setSalvando(true);
185	    setErro(null);
186	    setSucesso(false);
187	    try {
188	      await updateEmpresa({
189	        address: `${form.logradouro.trim()}, ${form.numero.trim()}`,
190	        cep: form.cep.trim(),
191	        neighborhood: form.neighborhood.trim(),
192	        city: form.city.trim(),
193	        state: form.state.trim(),
194	      });
195	      setSucesso(true);
196	      setTimeout(() => setSucesso(false), 2500);
197	    } catch (err) {
198	      setErro(err.message);
199	    } finally {
200	      setSalvando(false);
201	    }
202	  };
203	
204	  return (
205	    <div className="bg-white dark:bg-[#27272A] rounded-xl border p-6">
206	      <h2 className="font-semibold text-[#18181B] dark:text-[#F4F4F5] mb-1">Endereço do estabelecimento</h2>
207	      <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mb-4">Usado pro filtro de Estado/Cidade/Bairro/CEP e "restaurantes perto de mim" na home.</p>
208	
209	      {geocodeFalhou && (
210	        <div className="mb-4 bg-amber-50 dark:bg-amber-950/40 border border-amber-200 dark:border-amber-800 rounded-lg px-3 py-2 text-xs text-amber-700 dark:text-amber-400">
211	          ⚠️ Não conseguimos localizar esse endereço no mapa — confira se está completo e correto.
212	        </div>
213	      )}
214	
215	      {loading ? (
216	        <div className="flex justify-center py-6">
217	          <div className="w-6 h-6 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
218	        </div>
219	      ) : (
220	        <form onSubmit={salvar} className="space-y-3">
221	          <div className="grid grid-cols-3 gap-3">
222	            <div className="col-span-2">
223	              <label className="text-xs font-medium text-[#71717A] dark:text-[#A1A1AA]">Logradouro (rua/av.)</label>
224	              <input value={form.logradouro} onChange={(e) => setForm((f) => ({ ...f, logradouro: e.target.value }))}
225	                placeholder="Rua Exemplo"
226	                className="w-full mt-1 border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-lg px-3 py-2 text-sm outline-none focus:border-[#FF441F]" />
227	            </div>
228	            <div>
