230	              <input value={form.numero} onChange={(e) => setForm((f) => ({ ...f, numero: e.target.value }))}
231	                placeholder="123"
232	                className="w-full mt-1 border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-lg px-3 py-2 text-sm outline-none focus:border-[#FF441F]" />
233	            </div>
234	          </div>
235	          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
236	            <div>
237	              <label className="text-xs font-medium text-[#71717A] dark:text-[#A1A1AA]">CEP</label>
238	              <input value={form.cep} onChange={handleCepChange}
239	                placeholder="00000-000" maxLength={9}
