241	              {buscandoCep && <p className="text-[10px] text-[#71717A] dark:text-[#A1A1AA] mt-1">Buscando endereço...</p>}
242	            </div>
243	            <div>
244	              <label className="text-xs font-medium text-[#71717A] dark:text-[#A1A1AA]">Bairro</label>
245	              <input value={form.neighborhood} onChange={(e) => setForm((f) => ({ ...f, neighborhood: e.target.value }))}
246	                placeholder="Centro"
247	                className="w-full mt-1 border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-lg px-3 py-2 text-sm outline-none focus:border-[#FF441F]" />
248	            </div>
249	            <div>
250	              <label className="text-xs font-medium text-[#71717A] dark:text-[#A1A1AA]">Cidade</label>
