22	// Pino arrastável pra calibrar a localização exata do estabelecimento — o geocode
23	// automático (Nominatim) frequentemente erra rooftop-level em endereço brasileiro,
24	// o que quebra o filtro de raio pequeno (20m-100m) mesmo o cliente estando no lugar
25	// certo. Isso aqui é a fonte de verdade quando o dono confirma manualmente.
26	const MapaLocalizacaoPicker = ({ lat, lng, onChange }) => {
27	  const [posicao, setPosicao] = useState(
28	    lat != null && lng != null ? { lat, lng } : BRASIL_CENTRO,
29	  );
30	  const [zoom, setZoom] = useState(lat != null && lng != null ? 17 : 4);
31	  const [buscandoGps, setBuscandoGps] = useState(false);
32	  const mapRef = useRef(null);
33	
34	  useEffect(() => {
35	    if (lat != null && lng != null) {
36	      setPosicao({ lat, lng });
37	      setZoom((z) => (z < 15 ? 17 : z));
38	    }
39	  }, [lat, lng]);
40	
41	  const mover = (novoLat, novoLng) => {
42	    const p = { lat: novoLat, lng: novoLng };
43	    setPosicao(p);
