55	        setBuscandoGps(false);
56	      },
57	      () => setBuscandoGps(false),
58	      { enableHighAccuracy: true, timeout: 8000, maximumAge: 0 },
59	    );
60	  };
61	
62	  return (
63	    <div>
64	      <div className="flex items-center justify-between mb-2">
65	        <p className="text-xs text-[#71717A] dark:text-[#A1A1AA]">
66	          Arraste o pino até a porta do estabelecimento — quanto mais perto o zoom, mais preciso.
67	        </p>
68	        <button type="button" onClick={usarGpsAtual} disabled={buscandoGps}
69	          className="flex items-center gap-1 text-xs font-semibold text-[#FF441F] whitespace-nowrap ml-2 disabled:opacity-50">
70	          <Icon name="LocateFixed" size={14} className={buscandoGps ? 'animate-spin' : ''} />
71	          {buscandoGps ? 'Localizando...' : 'Usar GPS agora'}
72	        </button>
73	      </div>
74	
75	      <div className="rounded-xl overflow-hidden border border-[#E4E4E7] dark:border-[#3F3F46]" style={{ height: 280 }}>
76	        <MapContainer center={[posicao.lat, posicao.lng]} zoom={zoom} style={{ height: '100%', width: '100%' }}
77	          ref={mapRef}>
78	          <TileLayer
79	            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
80	            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
81	          <Marker
82	            position={[posicao.lat, posicao.lng]}
83	            draggable
84	            eventHandlers={{ dragend: (e) => { const p = e.target.getLatLng(); mover(p.lat, p.lng); } }} />
